// Hoje é sábado, 17 de outubro de 2026, 10:48 na cena.
export const TODAY = 17, NOW = 10 * 60 + 48;
const WEEK = ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb'], MONTHS = ['setembro', 'outubro', 'novembro'];
const wd = d => WEEK[new Date(2026, 9, d).getDay()];
