function skip(S, leaf) {
  const d = leaf.data, fs = S.store.focusSettings, work = d.phase === 'trabalho';
  const phase = work ? (d.round % fs.every === 0 ? 'pausa longa' : 'pausa curta') : 'trabalho';
  if (work) S.store.focusToday.push({ at: mmss(NOW), phase: 'trabalho', min: fs.work, task: S.store.tasks.find(t => t.focus)?.text });
  return { data: { phase, left: lenOf(S, phase), round: work ? d.round : d.round + 1, running: phase === 'trabalho' ? fs.autoWork : fs.autoBreak }, toast: `fase: ${phase}` };
}
